package tunnel

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)
func TestCloudflareCreateTunnelAndDNS(t *testing.T){var created,configured,dnsCreated bool;ts:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","application/json");result:=any(map[string]any{});switch{case r.URL.Path=="/zones":if r.URL.Query().Get("name")=="example.co.uk"{result=[]any{map[string]any{"id":"zone1","account":map[string]any{"id":"acct1"}}}}else{result=[]any{}};case strings.HasSuffix(r.URL.Path,"/cfd_tunnel")&&r.Method=="GET":result=[]any{};case strings.HasSuffix(r.URL.Path,"/cfd_tunnel")&&r.Method=="POST":created=true;result=map[string]any{"id":"tun1","token":"tunnel-secret"};case strings.Contains(r.URL.Path,"/configurations"):configured=true;result=map[string]any{};case strings.Contains(r.URL.Path,"dns_records")&&r.Method=="GET":result=[]any{};case strings.Contains(r.URL.Path,"dns_records")&&r.Method=="POST":dnsCreated=true;result=map[string]any{};default:t.Errorf("unexpected request %s %s",r.Method,r.URL.String());w.WriteHeader(404);return};_=json.NewEncoder(w).Encode(map[string]any{"success":true,"result":result})}));defer ts.Close();c:=cfClient{token:"test",client:ts.Client(),baseURL:ts.URL};tok,e:=configureNamedTunnel(context.Background(),c,"mcp.example.co.uk",8787);if e!=nil{t.Fatal(e)};if tok!="tunnel-secret"||!created||!configured||!dnsCreated{t.Fatalf("create path incomplete token=%q created=%v config=%v dns=%v",tok,created,configured,dnsCreated)}}
func TestCloudflareReuseTunnelAndDNSUpdate(t *testing.T){var tokenFetched,dnsUpdated bool;ts:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","application/json");var result any=map[string]any{};switch{case r.URL.Path=="/zones":result=[]any{map[string]any{"id":"z","account":map[string]any{"id":"a"}}};case strings.Contains(r.URL.Path,"/cfd_tunnel")&&r.URL.Query().Get("name")!="":result=[]any{map[string]any{"id":"existing"}};case strings.HasSuffix(r.URL.Path,"/existing/token"):tokenFetched=true;result="existing-token";case strings.Contains(r.URL.Path,"/configurations"):result=map[string]any{};case strings.Contains(r.URL.Path,"dns_records")&&r.Method=="GET":result=[]any{map[string]any{"id":"dns1"}};case strings.Contains(r.URL.Path,"dns_records")&&r.Method=="PUT":dnsUpdated=true;result=map[string]any{};default:t.Errorf("unexpected %s %s",r.Method,r.URL.String());w.WriteHeader(404);return};_=json.NewEncoder(w).Encode(map[string]any{"success":true,"result":result})}));defer ts.Close();c:=cfClient{token:"test",client:ts.Client(),baseURL:ts.URL};tok,e:=configureNamedTunnel(context.Background(),c,"mcp.example.com",8787);if e!=nil{t.Fatal(e)};if tok!="existing-token"||!tokenFetched||!dnsUpdated{t.Fatalf("reuse path incomplete: %s %v %v",tok,tokenFetched,dnsUpdated)}}
func TestCloudflareScopeErrorIsActionable(t *testing.T){ts:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.WriteHeader(403);_=json.NewEncoder(w).Encode(map[string]any{"success":false,"errors":[]any{map[string]any{"message":"permission denied"}}})}));defer ts.Close();c:=cfClient{client:ts.Client(),baseURL:ts.URL};e:=c.call(context.Background(),"GET","/zones",nil,nil);if e==nil||!strings.Contains(e.Error(),"Zone:DNS:Edit"){t.Fatalf("missing scope guidance: %v",e)}}
func TestWaitReadyHonorsContext(t *testing.T){ctx,cancel:=context.WithTimeout(context.Background(),20*time.Millisecond);defer cancel();if e:=waitReady(ctx,"http://127.0.0.1:1");e==nil{t.Fatal("expected context timeout")}}
func TestCloudflareTokenModeSkipsAPIAndKeepsTokenOutOfArgv(t *testing.T){d:=t.TempDir();argsPath,tokenPath:=filepath.Join(d,"args"),filepath.Join(d,"token");bin:=filepath.Join(d,"cloudflared");script:="#!/bin/sh\\nprintf '%s\\\\n' \\\"$@\\\" > '"+argsPath+"'\\nprintf '%s' \\\"$TUNNEL_TOKEN\\\" > '"+tokenPath+"'\\nexec sleep 30\\n";if e:=os.WriteFile(bin,[]byte(script),0755);e!=nil{t.Fatal(e)};t.Setenv("TUNNEL_TOKEN","secret-tunnel-token");t.Setenv("TUNNEL_HOST","");t.Setenv("CF_API_TOKEN","");t.Setenv("CLOUDFLARED_BIN",bin);_,stop,e:=(Cloudflare{}).Start(context.Background(),Config{Port:8787},"127.0.0.1:8787");if e!=nil{t.Fatal(e)};defer stop();deadline:=time.Now().Add(2*time.Second);for time.Now().Before(deadline){if _,e:=os.Stat(tokenPath);e==nil{break};time.Sleep(10*time.Millisecond)};args,_:=os.ReadFile(argsPath);token,_:=os.ReadFile(tokenPath);if strings.Contains(string(args),"secret-tunnel-token"){t.Fatalf("tunnel token leaked in argv: %s",args)};if string(token)!="secret-tunnel-token"{t.Fatalf("token missing from child environment: %q",token)}}
